    for _,id in ipairs(z.questIDs) do seen[id]=true end
    for _,id in ipairs(additions[z.areaID] or {}) do if not seen[id] then local q=HP.questData[id];local list=q.newForever and z.newQuestIDs or z.questIDs;list[#list+1]=id;seen[id]=true end end
    table.sort(z.newQuestIDs,function(a,b) local qa,qb=HP.foreverQuests[a],HP.foreverQuests[b];if qa.level==qb.level then return a<b end;return qa.level<qb.level end)
end
function HP.ResolveForeverMaps()
    if HP.zephrasMap then return end
    local map=HP.Call(C_Map and C_Map.GetBestMapForUnit,'player');local info=map and HP.Call(C_Map.GetMapInfo,map)
    if info and info.name=='Zephras Isle' then HP.zephrasMap=map end
    if not HP.zephrasMap then for _,root in ipairs({947,946}) do
        local children=HP.Call(C_Map and C_Map.GetMapChildrenInfo,root,nil,true)
        for _,child in ipairs(type(children)=='table' and children or {}) do if child.name=='Zephras Isle' then HP.zephrasMap=child.mapID end end
    end end
    if not HP.zephrasMap then return end
    for _,z in ipairs(HP.zoneCatalog) do if z.areaID==16593 then z.mapID=HP.zephrasMap end end
    for _,r in pairs(HP.routes) do if r.id=='zone_16593' then r.mapID=HP.zephrasMap end end
    for _,entities in ipairs({HP.npcData,HP.objectData}) do for _,entity in pairs(entities) do
        for _,point in ipairs(entity.spawns or {}) do if point.zoneID==16593 then point.mapID=HP.zephrasMap end end
        if entity.location and entity.location.zoneID==16593 then entity.location.mapID=HP.zephrasMap end
    end end
end
